/**
 * MCP reader for the DeepSeek Harness desktop.
 *
 * WHY THIS PLUGIN EXISTS
 *
 * dsh has no global `mcp.json`: live servers are either the `mcp-manager` row's
 * `config.servers` inside the profile composition, or registrations a plugin
 * contributes at runtime. The profile patch is `never_touch` — it is also the
 * settings surface the GUI writes — so the bridge cannot rewrite it without
 * gambling with the user's own configuration. What it CAN do is own one file:
 *
 *     ~/.dsh/agent-config-bridge/mcp.json      (generated by `bridge apply`)
 *              │  read at activation, re-read on change
 *              ▼
 *     ctx.mcpManager.register(name, entry)     (one server per entry)
 *
 * That is the whole bridge. The document is Claude-shaped, exactly what every
 * other JSON target receives, so a human debugging it sees the same fields the
 * authoritative source has; this plugin converts each entry to the manager's
 * registration shape (transport + endpoint) and keeps the fleet reconciled:
 * changed entries are rebuilt, removed entries are withdrawn, and a document
 * that is missing or half-written changes nothing at all.
 *
 * WHY A PUBLIC MOUNT ROW IS STILL NEEDED
 *
 * dsh does not auto-load an extension directory; a plugin exists only when the
 * Cordis composition names it. `scripts/install-dsh.js` installs this file and
 * prints the one row (`auto_load: false` in the target manifest is the honest
 * way to say so). Until that row exists, nothing here runs.
 *
 * WHY IMPORTS ARE NODE BUILTINS ONLY
 *
 * This file is installed under `~/.dsh/plugins/`, outside the dsh installation,
 * so a bare `import '@deepseek-ai/dsh-mcp-client'` cannot resolve at runtime.
 * Everything comes from the context the harness hands the plugin
 * (`ctx.mcpManager`, `ctx.effect`, `ctx.logger`) plus `node:fs`.
 *
 * Interplay worth knowing: `/mcp` (from the sibling commands plugin) lists
 * these servers with origin `plugin` and can `restart` them, because the
 * manager treats a registration exactly like a configured entry.
 */

import { existsSync, readFileSync, unwatchFile, watchFile, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

export const name = 'agent-config-mcp';

/** A registration is meaningless without the manager it belongs to. */
export const inject = ['mcpManager'];

/** The MCP server-name namespace shape `dsh-mcp-manager` accepts. */
const SERVER_NAME = /^[A-Za-z0-9_-]{1,32}$/;

/** Poll interval for the generated document. Windows-safe, and one stat per tick. */
const WATCH_INTERVAL_MS = 1000;

/** How often the status sidecar is refreshed while nothing transitions. */
const STATUS_INTERVAL_MS = 5000;

/** Upper bound on a diagnostic written to the sidecar. */
const MAX_REASON = 300;

/** The harness home, resolved the way dsh itself resolves it. */
export const homeDir = () => process.env.DSH_HOME || join(homedir(), '.dsh');

/** The document `bridge apply` maintains. Kept in one place: the manifest points here. */
export const documentPath = (home = homeDir()) => join(home, 'agent-config-bridge', 'mcp.json');

/** Where the live fleet is reported (names, states, tool counts — never credentials). */
export const statusPath = (home = homeDir()) => join(home, 'agent-config-bridge', 'mcp-status.json');

const stringRecord = (value) => {
  const out = {};
  if (!value || typeof value !== 'object' || Array.isArray(value)) return out;
  for (const [key, inner] of Object.entries(value)) {
    if (typeof inner === 'string') out[key] = inner;
  }
  return out;
};

/**
 * Translate the authoritative (Claude-shaped) document into `mcp-manager`
 * registrations. Pure: no I/O, so the shapes are proven by tests rather than by
 * watching a running harness.
 *
 * Anything outside the common shape is reported instead of dropped — a server
 * that vanishes because a field was spelled differently is the failure this
 * function exists to make visible.
 *
 * @param {unknown} raw - the `mcpServers` object of the generated document.
 * @returns {{entries: Record<string, object>, skipped: Array<{name: string, reason: string}>}}
 */
export const translateServers = (raw) => {
  const entries = {};
  const skipped = [];
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return { entries, skipped };

  for (const [serverName, def] of Object.entries(raw)) {
    if (!SERVER_NAME.test(serverName)) {
      skipped.push({ name: serverName, reason: 'name must match [A-Za-z0-9_-]{1,32}' });
      continue;
    }
    if (!def || typeof def !== 'object' || Array.isArray(def)) {
      skipped.push({ name: serverName, reason: 'entry is not an object' });
      continue;
    }
    if (typeof def.url === 'string' && def.url.length > 0) {
      entries[serverName] = {
        transport: 'streamable-http',
        url: def.url,
        headers: stringRecord(def.headers),
      };
      continue;
    }
    if (typeof def.command === 'string' && def.command.length > 0) {
      const entry = {
        transport: 'stdio',
        command: def.command,
        args: Array.isArray(def.args) ? def.args.map(String) : [],
        env: stringRecord(def.env),
      };
      // `cwd` is a real stdio field. Dropping it starts servers in whatever
      // directory the session happens to be in, which is how a server that
      // resolves data relative to its own checkout reads the wrong files.
      if (typeof def.cwd === 'string' && def.cwd.length > 0) entry.cwd = def.cwd;
      entries[serverName] = entry;
      continue;
    }
    skipped.push({ name: serverName, reason: 'neither "url" nor "command" is present' });
  }

  return { entries, skipped };
};

const briefStatus = (view) => {
  const status = view?.status ?? {};
  const out = { name: view?.name ?? '', state: status.state ?? 'unknown' };
  if (typeof status.toolCount === 'number') out.toolCount = status.toolCount;
  if (typeof status.attempt === 'number' && status.attempt > 0) out.attempt = status.attempt;
  if (typeof status.lastError === 'string') out.reason = status.lastError.slice(0, MAX_REASON);
  return out;
};

/**
 * Build the synchronizer the plugin runs.
 *
 * Exported and transport-free so tests drive it against a temp file and a stub
 * manager. The rules are the point:
 *
 *   - a changed entry is disposed before it is re-registered (the manager
 *     refuses a duplicate name, so order is not cosmetic);
 *   - removal happens only from a document that actually parsed;
 *   - one server failing to register does not abort the rest.
 *
 * @param {object} args
 * @param {{register: Function, list: Function}} args.manager - `ctx.mcpManager`.
 * @param {string} args.file - generated document.
 * @param {{warn?: Function, info?: Function}} [args.log]
 * @param {string|null} [args.statusFile] - sidecar path, or null to disable.
 */
export const createSync = ({ manager, file, log = {}, statusFile = null }) => {
  /** @type {Map<string, {entry: object, dispose: Function}>} */
  const live = new Map();
  let lastStatus = '';
  let lastSkipped = [];

  const writeStatus = () => {
    if (!statusFile) return;
    try {
      const views = typeof manager.list === 'function' ? manager.list() : [];
      const wanted = new Set(live.keys());
      const document = {
        updatedAt: new Date().toISOString(),
        source: file,
        registered: live.size,
        skipped: lastSkipped,
        servers: views.filter((view) => wanted.has(view?.name)).map(briefStatus),
      };
      const text = `${JSON.stringify(document, null, 2)}\n`;
      if (text === lastStatus) return;
      lastStatus = text;
      writeFileSync(statusFile, text);
    } catch {
      // Diagnostics must never take the fleet down.
    }
  };

  const release = (serverName) => {
    const record = live.get(serverName);
    if (!record) return;
    live.delete(serverName);
    try {
      record.dispose();
    } catch (err) {
      log.warn?.(`agent-config-mcp: could not release ${serverName}: ${err?.message ?? err}`);
    }
  };

  const shutdown = () => {
    for (const serverName of [...live.keys()]) release(serverName);
  };

  /**
   * Reconcile the live registrations against the document on disk.
   * @returns {{registered: number, skipped: Array<{name: string, reason: string}>}}
   */
  const sync = () => {
    if (!existsSync(file)) {
      log.info?.(`agent-config-mcp: no MCP document at ${file}; nothing registered`);
      lastSkipped = [];
      writeStatus();
      return { registered: live.size, skipped: [] };
    }

    let parsed;
    try {
      // Tolerate a UTF-8 BOM: Windows editors and PowerShell add one, and a
      // document the reader refuses to parse leaves the fleet stuck on the
      // previous set with no visible reason.
      parsed = JSON.parse(readFileSync(file, 'utf8').replace(/^\uFEFF/, ''));
    } catch (err) {
      // Failing still, not down: an editor mid-save or an interrupted `apply`
      // must not withdraw a working fleet.
      log.warn?.(
        `agent-config-mcp: ${file} is not valid JSON (${err?.message ?? err}); keeping the live fleet`,
      );
      return { registered: live.size, skipped: lastSkipped };
    }

    const { entries, skipped } = translateServers(parsed?.mcpServers ?? {});
    lastSkipped = skipped;
    for (const problem of skipped) {
      log.warn?.(`agent-config-mcp: skipping ${problem.name}: ${problem.reason}`);
    }

    // Withdraw or rebuild what changed; removals first, because the manager
    // refuses a name that is still registered.
    for (const serverName of [...live.keys()]) {
      const previous = live.get(serverName);
      if (!Object.hasOwn(entries, serverName)) {
        release(serverName);
        continue;
      }
      if (JSON.stringify(previous.entry) !== JSON.stringify(entries[serverName])) {
        release(serverName);
      }
    }

    for (const [serverName, entry] of Object.entries(entries)) {
      if (live.has(serverName)) continue;
      try {
        live.set(serverName, { entry, dispose: manager.register(serverName, entry) });
      } catch (err) {
        log.warn?.(`agent-config-mcp: cannot register ${serverName}: ${err?.message ?? err}`);
      }
    }

    writeStatus();
    return { registered: live.size, skipped };
  };

  return { sync, shutdown, writeStatus, live };
};

/**
 * Mount the reader.
 *
 * Config (all optional; defaults suit the installed layout):
 *   file        document to read
 *   statusFile  sidecar path; `status: false` disables it
 *   watch       `false` disables the change watcher (tests, one-shot runs)
 */
export function apply(ctx, config = {}) {
  const file = typeof config.file === 'string' && config.file ? config.file : documentPath();
  const statusFile =
    config.status === false
      ? null
      : typeof config.statusFile === 'string' && config.statusFile
        ? config.statusFile
        : statusPath();

  const log = {
    warn: (message) => {
      try {
        ctx.logger?.warn?.(message);
      } catch {
        // the harness logger is optional
      }
      process.stderr.write(`${message}\n`);
    },
    info: (message) => {
      try {
        ctx.logger?.info?.(message);
      } catch {
        // the harness logger is optional
      }
    },
  };

  const sync = createSync({ manager: ctx.mcpManager, file, log, statusFile });

  ctx.effect(() => {
    sync.sync();

    // Status transitions (connecting / connected / failed) are the useful part
    // of the sidecar and are not observable from the document watcher.
    const statusTimer = statusFile ? setInterval(() => sync.writeStatus(), STATUS_INTERVAL_MS) : null;

    if (config.watch !== false) {
      // Polling on purpose: a rename-style atomic save replaces the inode, which
      // an inode watcher misses, and this file is written by another tool.
      watchFile(file, { interval: WATCH_INTERVAL_MS }, () => {
        const result = sync.sync();
        log.info?.(`agent-config-mcp: document changed; ${result.registered} server(s) registered`);
      });
    }

    return () => {
      if (statusTimer) clearInterval(statusTimer);
      if (config.watch !== false) unwatchFile(file);
      sync.shutdown();
    };
  });
}
